import{_ as e,o as t,c as o,a3 as i}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"出版后记","description":"","frontmatter":{},"headers":[],"relativePath":"books/jingying-weilai/15-出版后记.md","filePath":"books/jingying-weilai/15-出版后记.md","lastUpdated":1795076791000}'),r={name:"books/jingying-weilai/15-出版后记.md"};function n(_,a,s,p,l,d){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="出版后记" tabindex="-1">出版后记 <a class="header-anchor" href="#出版后记" aria-label="Permalink to &quot;出版后记&quot;">​</a></h1><h2 id="人民出版社社长-黄书元" tabindex="-1">人民出版社社长 黄书元 <a class="header-anchor" href="#人民出版社社长-黄书元" aria-label="Permalink to &quot;人民出版社社长 黄书元&quot;">​</a></h2><p>《经营未来：李明博自传》历经几个月的精雕细琢，终于和中国广大读者见面了。作为该书的出版人，我们的内心充满着欢欣。中国有一句老话叫“有志者，事竟成”。如果你细细品读此书，就不难发现这样的警句格言不仅属于中国，也属于韩国，属于世界。</p><p>读罢此书，我们不禁深深感佩于李明博先生在书中所传达的一种信念和精神：一种怀揣志向和梦想、遇到挫折绝不放弃的精神，一种在困境中总是拼尽全力去挑战、去奋斗的精神。在此，我们也不禁想提起另一位有着类似精神气质的韩国友人——拓荒建苑的“愚公”成范永先生。</p><p>2007年，在中韩建交十五周年之际，我们应韩国“思索之苑”的创建人成范永先生邀请，参加该苑正式开放十五周年庆典。成范永先生从青年时期起为了实现建造一个盆景艺术苑的理想，放弃在首尔的舒适生活，单身一人来到当时还是乱石荒岗的济州岛，开荒建苑，克服常人难以想象的艰难困苦，终于在十五年前建成了世界一流的盆景艺术苑。中国两任国家主席江泽民、胡锦涛同志以及世界许多名人都曾先后参观过该苑。可以说，成范永先生是一个追求理想、为了理想而奋斗并最终实现理想的典范。</p><p>也许是由于“英雄相惜”，在访韩期间，成范永先生特意向我们提起和介绍了在韩国已经家喻户晓的传奇人物李明博先生的有关事迹。我们也由此产生了把李明博先生奋斗精神和独特经历全面介绍给中国读者的愿望。</p><p>在李明博先生当选为韩国第17届总统前夕，我们见到了《经营未来：李明博自传》的中文译稿。书稿内容读来是如此真切和动人心弦，不仅有在韩国民众中流传的传奇故事，更有传主在经历这些故事时的心路历程和理性思考。</p><p>我们希望中国广大读者特别是青年朋友们能够在本书中得到启迪，更希望中国有千万个自强不息人物成长起来。我们热忱地祝福韩国在李明博先生的领导下更加强盛！祝福中韩两国合作伙伴关系得到进一步发展！</p>',8)])])}const m=e(r,[["render",n]]);export{h as __pageData,m as default};
